    """;

    /// <summary>
    /// The document head, including the theme bootstrap and the inlined stylesheet.
    /// </summary>
    public static string Head(string title) =>
        "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        + "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
        + $"<title>{WebUtility.HtmlEncode(title)}</title>"
        + ThemeScript
        + "<style>" + Css + "</style></head>";

    /// <summary>
    /// Applies the stored theme before anything paints. Blocking, and ahead of the stylesheet, on
    /// purpose: deferring it lets the page paint light and then snap to dark, which is a visible flash.
    /// <c>?theme=light|dark</c> forces a ground for one page view without touching the stored preference.
    /// With nothing stored the attribute is left off entirely, so the daisyUI themes' own
    /// <c>prefers-color-scheme</c> rules follow the OS.
    /// </summary>
    private const string ThemeScript = """
    <script>(function(){var K='rastgo-theme';var f=new URLSearchParams(location.search).get('theme');var s=null;try{s=localStorage.getItem(K)}catch(e){}var t=f==='dark'?'harness-dark':f==='light'?'harness':s;if(t)document.documentElement.dataset.theme=t})();</script>
    """;

    /// <summary>
    /// The Rastgo lockup, themed. The brand gold is bright — 1.5:1 on white — so on the light ground it
    /// can only be a FILL: the star sits in a gold tile carrying a dark glyph. The wordmark is page ink
    /// with the "A" in <c>accent</c>, which is the darkened gold on light and the plain gold on dark, so
    /// it reads on either ground.
    /// </summary>
    public const string Logo = """
    <span class="flex items-center gap-2"><span class="bg-primary size-6 rounded-[7px] grid place-items-center"><svg viewBox="0 0 120 120" class="size-[70%]" aria-hidden="true"><path fill-rule="evenodd" fill="#2a2000" d="M60,0 75,45 120,60 75,75 60,120 45,75 0,60 45,45 Z M60,28 68,52 92,60 68,68 60,92 52,68 28,60 52,52 Z"/></svg></span><span class="text-sm font-semibold tracking-[0.08em]">R<span class="text-accent">A</span>STGO</span></span>
    """;

    /// <summary>The theme toggle button, right-docked in each page's toolbar. Filled in by the script.</summary>
    public const string ThemeToggleButton =
        """<button type="button" data-theme-toggle class="btn btn-xs btn-ghost border-base-300 grid size-7 place-items-center border p-0"></button>""";

    // ---- the shared design vocabulary --------------------------------------

    /// <summary>The colour a status is drawn in, in each of the forms the pages need.</summary>
    /// <param name="Text">Foreground only — a KPI number, a status dot.</param>
    /// <param name="Solid">A filled pill: background plus the matching readable foreground.</param>
    /// <param name="Bar">Background only — a strip cell, a hero segment, a legend swatch.</param>
    public readonly record struct StatusTone(string Text, string Solid, string Bar);

    /// <summary>
    /// Status → daisyUI semantic colour. The theme's info/success/warning/error are "fixture state only"
    /// for the components; on a health page status IS the content, which is exactly what they are for.
    /// <para>
    /// Error and Skipped are deliberately NOT red. "The check could not run" and "the data is wrong" are
    /// different facts, and colouring them the same buries the second in the first. Error takes
    /// <c>secondary</c> (ink-2) rather than <c>neutral</c> because neutral is only 3.2:1 behind white and
    /// a status pill has to be read, not merely noticed — which also leaves <c>neutral</c> free to mean
    /// Skipped, a distinction the previous two near-identical greys could not carry.
    /// </para>
    /// <para>
    /// WRITTEN OUT IN FULL, never composed as <c>"bg-" + token</c>: see the note on <see cref="Css"/>.
    /// </para>
    /// </summary>
    public static StatusTone Tone(HealthStatus status) => status switch
    {
        HealthStatus.Fail => new("text-error", "bg-error text-error-content", "bg-error"),
        HealthStatus.Error => new("text-secondary", "bg-secondary text-secondary-content", "bg-secondary"),
        HealthStatus.Warn => new("text-warning", "bg-warning text-warning-content", "bg-warning"),
        HealthStatus.Pass => new("text-success", "bg-success text-success-content", "bg-success"),
        _ => new("text-neutral", "bg-neutral text-neutral-content", "bg-neutral"),
    };

    /// <summary>Statuses worst-first, matching <see cref="CheckRunner.Rank"/> — the order count chips read in.</summary>
    public static readonly HealthStatus[] ChipOrder =
        [HealthStatus.Fail, HealthStatus.Error, HealthStatus.Warn, HealthStatus.Skipped, HealthStatus.Pass];

    /// <summary>The four summary cards, in the same worst-first order.</summary>
    public static readonly HealthStatus[] KpiOrder =
        [HealthStatus.Fail, HealthStatus.Error, HealthStatus.Warn, HealthStatus.Pass];

    /// <summary>
    /// A fold wrapper: an outer element carrying the animated <c>grid-template-rows</c> track and an inner
    /// one that clips. Anything <c>sticky</c> must stay OUTSIDE this — the inner <c>overflow-hidden</c>
    /// would break it.
    /// </summary>
    public static string Slide(string inner, bool folded = false) =>
        $"<div data-slide class=\"grid grid-rows-[{(folded ? "0fr" : "1fr")}] transition-[grid-template-rows] duration-200 ease-out\">"
        + $"<div class=\"overflow-hidden\">{inner}</div></div>";

    /// <summary>The fold caret. Rotates rather than swapping glyphs, so the transition is continuous.</summary>
    public static string Caret(bool folded = false) =>
        $"<span data-caret class=\"text-base-content/35 inline-block w-2.5 shrink-0 text-[9px] transition-transform duration-200{(folded ? " -rotate-90" : "")}\">▾</span>";

    /// <summary>
    /// The "i" cue, carrying the tip ITSELF rather than sitting inside a header that carries it: a tooltip
    /// anchors to its target's box, and a category header is the full width of the pane, so anchoring
    /// there parks the tip in the middle of the screen nowhere near what you hovered. It is also the
    /// affordance — a tooltip with nothing to point at is one nobody discovers. Focusable, so it is
    /// reachable without a mouse. Empty when there is nothing to say.
    /// </summary>
    public static string InfoCue(string? tip) => string.IsNullOrWhiteSpace(tip) ? "" :
        $"<span tabindex=\"0\" role=\"button\" aria-label=\"What this checks\" data-tip=\"{WebUtility.HtmlEncode(tip)}\" "
        + "class=\"border-base-content/30 text-base-content/40 hover:text-base-content hover:border-base-content "
        + "grid size-3.5 shrink-0 cursor-help place-items-center rounded-full border text-[8px] font-bold transition-colors\">i</span>";

    /// <summary>
    /// The script fragment both pages open with — no <c>&lt;script&gt;</c> tags and no wrapper of its own,
    /// so each renderer appends its page behaviour inside the same IIFE.
    /// </summary>
    public const string SharedScript = """

    /* ---- tooltips ---------------------------------------------------------
       One floating node, delegated off [data-tip]. The tips live inside a
       scrolling rail and an overflow-clipped section, where a CSS-only tooltip
       gets cut off by its own container. Native `title` is not a substitute: it
       waits about a second, cannot be styled, and never appears for keyboard
       users. */
    const tip = document.createElement('div');
    tip.setAttribute('role', 'tooltip');
    tip.className = 'pointer-events-none fixed z-[100] max-w-[21rem] rounded-field bg-secondary text-secondary-content px-2.5 py-1.5 text-xs leading-snug shadow-lg opacity-0 transition-opacity duration-100';
    document.body.appendChild(tip);

    let tipTimer = null, tipFor = null;

    function showTip(target) {
      tipFor = target;
      tip.textContent = target.dataset.tip;
      /* Measure at the origin first: the node must have layout to be placed, and
         max-width keeps that measurement stable wherever it starts. */
      tip.style.left = '0px';
      tip.style.top = '0px';
      const anchor = target.getBoundingClientRect(), self = tip.getBoundingClientRect(), gap = 8;
      const top = anchor.top - self.height - gap;
      tip.style.top = (top < 4 ? anchor.bottom + gap : top) + 'px';
      tip.style.left = Math.max(6, Math.min(anchor.left + anchor.width / 2 - self.width / 2, window.innerWidth - self.width - 6)) + 'px';
      tip.style.opacity = '1';
    }

    function hideTip() { clearTimeout(tipTimer); tipFor = null; tip.style.opacity = '0'; }

    document.addEventListener('pointerover', e => {
      const target = e.target.closest?.('[data-tip]');
      if (!target || target === tipFor) return;
      clearTimeout(tipTimer);
      tipTimer = setTimeout(() => showTip(target), 180);
    });
    document.addEventListener('pointerout', e => {
      const from = e.target.closest?.('[data-tip]');
      /* Moving between children of the same target is not leaving it. */
      if (from && e.relatedTarget?.closest?.('[data-tip]') !== from) hideTip();
    });
    document.addEventListener('focusin', e => { const t = e.target.closest?.('[data-tip]'); if (t) showTip(t); });
    document.addEventListener('focusout', hideTip);
    document.addEventListener('keydown', e => { if (e.key === 'Escape') hideTip(); });
    /* A tip anchored to a row that just scrolled away is worse than no tip. */
    window.addEventListener('scroll', hideTip, true);

    /* ---- theme toggle -----------------------------------------------------
       Shows the icon of the theme you would GET, not the one you are in — the
       near-universal convention, and the one that makes the button read as an
       action rather than a status light. The tooltip says it in words, because a
       lone icon is ambiguous to anyone who has not met the convention.

       With nothing stored the page follows the OS, so the first click has to
       resolve that to a concrete choice rather than toggling an attribute that
       is not there yet. */
    const ICON = {
      sun: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" class="size-3.5" aria-hidden="true"><circle cx="12" cy="12" r="4" /><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M6.3 17.7l-1.4 1.4M19.1 4.9l-1.4 1.4" /></svg>`,
      moon: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="size-3.5" aria-hidden="true"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z" /></svg>`,
    };

    const THEME_KEY = 'rastgo-theme';
    const themeButton = document.querySelector('[data-theme-toggle]');

    const isDark = () =>
      document.documentElement.dataset.theme
        ? document.documentElement.dataset.theme === 'harness-dark'
        : window.matchMedia?.('(prefers-color-scheme: dark)').matches === true;

    function paintThemeButton() {
      const toLight = isDark();
      themeButton.innerHTML = toLight ? ICON.sun : ICON.moon;
      themeButton.setAttribute('aria-label', toLight ? 'Switch to light theme' : 'Switch to dark theme');
      themeButton.dataset.tip = toLight ? 'Switch to light theme' : 'Switch to dark theme';
    }

    themeButton.addEventListener('click', () => {
      document.documentElement.dataset.theme = isDark() ? 'harness' : 'harness-dark';
      try { localStorage.setItem(THEME_KEY, document.documentElement.dataset.theme); }
      catch (e) { /* private window — the choice just does not outlive the page. */ }
      paintThemeButton();
    });

    /* Follow the OS while the reader has expressed no preference of their own. */
    window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener('change', () => {
      if (!document.documentElement.dataset.theme) paintThemeButton();
    });

    paintThemeButton();

    /* ---- folding ----------------------------------------------------------
       One primitive for every level on both pages. Heights animate through
       `grid-template-rows: 1fr -> 0fr` rather than max-height, so the slide is
       correct for content of unknown height and needs no measuring; the
       reduced-motion reset in the stylesheet turns it off. Nothing is removed
       from the DOM, so a re-expand costs nothing and native Ctrl+F keeps
       working. */
    function setFold(header, wrapper, folded) {
      if (!wrapper) return;
      wrapper.classList.toggle('grid-rows-[0fr]', folded);
      wrapper.classList.toggle('grid-rows-[1fr]', !folded);
      header?.querySelector('[data-caret]')?.classList.toggle('-rotate-90', folded);
      header?.setAttribute('aria-expanded', String(!folded));
    }

    const isFolded = wrapper => wrapper?.classList.contains('grid-rows-[0fr]');

    /* The slide wrapper a header controls. Usually its next sibling — but the
       rail's fold caret sits in a flex row beside the jump link, so there the
       wrapper is the sibling of that ROW. Checking both is what makes one bind
       work for every level. */
    const bodyOf = header =>
      [header.nextElementSibling, header.parentElement?.nextElementSibling].find(el => el?.matches('[data-slide]')) ?? null;

    """;
}
